/** Format generated text before identity hashing or writing. */
import { formatGeneratedText } from '../lib/format-tools.mjs';

const cache = new Map();

/**
 * Return the formatter's output for one generated file.
 *
 * Generated bytes and the manifest hash are computed from this result, so the
 * order is: generate -> format -> hash -> write. A repeated identical input is
 * served from memory; the formatter stays the only source of layout.
 */
export async function formatGeneratedOutput(relativePath, content) {
  const key = `${relativePath}\u0000${content}`;
  if (cache.has(key)) {
    return cache.get(key);
  }
  const formatted = await formatGeneratedText(relativePath, content);
  cache.set(key, formatted);
  return formatted;
}
